package java.util.concurrent.atomic;
public class AtomicLongArray implements java.io.Serializable {private final long[] values;public AtomicLongArray(int n){values=new long[n];}public AtomicLongArray(long[] a){values=new long[a.length];System.arraycopy(a,0,values,0,a.length);}public int length(){return values.length;}public synchronized long get(int i){return values[i];}public synchronized void set(int i,long v){values[i]=v;}public void lazySet(int i,long v){set(i,v);}public synchronized long getAndSet(int i,long v){long o=values[i];values[i]=v;return o;}public synchronized boolean compareAndSet(int i,long e,long v){if(values[i]!=e)return false;values[i]=v;return true;}public boolean weakCompareAndSet(int i,long e,long v){return compareAndSet(i,e,v);}public synchronized long getAndIncrement(int i){return values[i]++;}public synchronized long getAndDecrement(int i){return values[i]--;}public synchronized long getAndAdd(int i,long d){long v=values[i];values[i]+=d;return v;}public synchronized long incrementAndGet(int i){return ++values[i];}public synchronized long decrementAndGet(int i){return --values[i];}public synchronized long addAndGet(int i,long d){return values[i]+=d;}public String toString(){StringBuilder b=new StringBuilder("[");for(int i=0;i<length();i++){if(i>0)b.append(", ");b.append(values[i]);}return b.append(']').toString();} public final synchronized long getAndUpdate(int i,java.util.function.LongUnaryOperator f){long o=values[i];values[i]=f.applyAsLong(o);return o;} public final synchronized long updateAndGet(int i,java.util.function.LongUnaryOperator f){long v=f.applyAsLong(values[i]);values[i]=v;return v;} public final synchronized long getAndAccumulate(int i,long x,java.util.function.LongBinaryOperator f){long o=values[i];values[i]=f.applyAsLong(o,x);return o;} public final synchronized long accumulateAndGet(int i,long x,java.util.function.LongBinaryOperator f){long v=f.applyAsLong(values[i],x);values[i]=v;return v;}}
